#!/usr/bin/env python3
# AI DISCLAIMER: All of the text in this file was generated by AI.
"""sampler_vm.py (kit v10, G016 diagnosis stage): every 5 s, one CSV line: mono_ns (CLOCK_MONOTONIC, the clock of
bpftrace's nsecs and of the LMDB page-event log), unix_s, height (monerod's /get_height on 127.0.0.1), and the node's
utime+stime ticks. Ends when the node's process is gone. No network access except RPC on 127.0.0.1.
usage: python3 -I sampler_vm.py <rpc port> <node pid> <out csv>"""
import json, sys, time, urllib.request
port, pid, out = sys.argv[1], int(sys.argv[2]), sys.argv[3]


def height():
    try:
        req = urllib.request.Request("http://127.0.0.1:%s/get_height" % port, data=b"{}", method="POST")
        with urllib.request.urlopen(req, timeout=4) as r:
            return json.load(r).get("height", "")
    except Exception:
        return ""


def cpu():
    try:
        f = open("/proc/%d/stat" % pid).read().rsplit(")", 1)[1].split()
        return int(f[11]) + int(f[12])
    except Exception:
        return None


with open(out, "w") as o:
    o.write("mono_ns,unix_s,height,cpu_ticks\n")
    while True:
        c = cpu()
        if c is None:
            break
        o.write("%d,%.3f,%s,%d\n" % (time.monotonic_ns(), time.time(), height(), c))
        o.flush()
        time.sleep(5)
